function supported(c){const rule=window.RULES_DATA?.coreRules?.find(r=>r.id===RULE&&r.source_verified),typeRule=window.RULES_DATA?.campaignTypes?.find(r=>r.id===TYPE&&r.source_verified),type=typeof cpCampaignType==='function'?cpCampaignType(c):null;return !!c&&String(c.edition).toUpperCase()==='N26'&&!!rule&&!!typeRule&&(c.campaignTypeId===TYPE||type?.id===TYPE);}
