function members(c,gangs=localGangs()){return (c.members||[]).map(m=>({member:m,gang:gangs.find(g=>g.id===m.gangId&&String(g.edition).toUpperCase()==='N26')})).filter(r=>r.gang);}
function playerId(m,g){const owner=m.ownerId||m.userId||m.accountId||g.sourceOwnerId||g.remoteOwnerId||g.ownerId;if(owner)return 'account:'+owner;const name=String(m.player||m.username||'').trim().normalize('NFKC').toLowerCase();return name?'player:'+name:'member:'+(m.id||g.id);}
