 const grouped=new Map();for(const {member:m,gang:g}of members(c,gangs)){const key=playerId(m,g);if(!grouped.has(key))grouped.set(key,{playerId:key,name:String(m.player||m.username||g.owner||g.name),gangs:[]});if(!grouped.get(key).gangs.some(x=>x.id===g.id))grouped.get(key).gangs.push(g);}return [...grouped.values()];
