 const adopted=new Set((state(c).challenges||[]).map(x=>x.legacyBattleId).filter(Boolean));return (c.battles||[]).map((b,index)=>({b,index})).filter(({b})=>b.challenge&&!adopted.has(b.id)).map(({b,index})=>{
  const ids=(b.participants||[]).map(p=>p.gangId||p.gang_id).filter(Boolean),a=b.attacker||b.participants?.find(p=>p.role==='attacker')?.gangId||ids[0]||'',d=b.defender||b.participants?.find(p=>p.role==='defender')?.gangId||ids.find(g=>g!==a)||'';
  const cy=Number(b.cycle)||0,stakeId=b.territoryId||'',p=b.campaignPhase||phaseAt(c,cy);return {id:'legacy:'+b.id,legacyBattleId:b.id,cycle:cy,phase:p,status:b.status==='Played'?'played':b.status==='Declined'?'declined':!d||!stakeId||!cy||!p?'draft':'issued',challengerGangId:a,defenderGangId:d,challengerPlayerId:playerFor(c,a,gangs)?.playerId||'',defenderPlayerId:playerFor(c,d,gangs)?.playerId||'',stakeId,sequence:index+1,issuedAt:b.createdAt||b.date||'',legacy:true};
 });
