function challengeStatus(ch,c){if(['declined','played','draft'].includes(ch.status))return ch.status;const session=(c.sessions||[]).find(s=>s.challengeId===ch.id||s.id===ch.sessionId);if(session?.status==='Completed'||session?.stage==='completed'||(c.battles||[]).some(b=>b.challengeId===ch.id&&b.status==='Played'))return 'played';return ch.status;}
