 const basis={method:cycle(c)===1?'random':'ascending-rating',draws:[],tieRolls:[]};
 if(cycle(c)===1){for(let i=order.length-1;i>0;i--){const j=die(i+1)-1;if(!Number.isInteger(j)||j<0||j>i)throw Error('Invalid random result');basis.draws.push({size:i+1,value:j+1});[order[i],order[j]]=[order[j],order[i]];}}
