  order.sort((a,b)=>a.rating-b.rating);let attempts=0;
  const breakTie=group=>{if(group.length<2)return group;if(++attempts>64)throw Error(T('The tie is unresolved. Roll again.','동률을 해결하지 못했습니다. 다시 굴리세요.'));const rolled=group.map(p=>({p,roll:die(6)}));basis.tieRolls.push(rolled.map(x=>({playerId:x.p.playerId,value:x.roll})));rolled.sort((a,b)=>b.roll-a.roll);const out=[];for(let i=0;i<rolled.length;){let j=i+1;while(j<rolled.length&&rolled[j].roll===rolled[i].roll)j++;out.push(...breakTie(rolled.slice(i,j).map(x=>x.p)));i=j;}return out;};
  const sorted=[];for(let i=0;i<order.length;){let j=i+1;while(j<order.length&&order[j].rating===order[i].rating)j++;sorted.push(...breakTie(order.slice(i,j)));i=j;}order=sorted;
