 const turn=records(c)[String(cy)].order.findIndex(entry=>entry.playerId===challenger.playerId),challengeId=uid(),at=clock(),key=`challenges:cycle:${cy}:turn:${turn}:issue:${permission.ordinal}`;
 return await api().apply(c,{key,label:T('Issue campaign challenge','캠페인 도전 신청'),gangIds:[],mutate(draft){const d=draft.campaign;assertLive(c,cy,p);const ready=issueAllowed(d,gangId,{timeRemaining},draft.gangs);if(!ready.ok||ready.ordinal!==permission.ordinal||!legalStakes(d,gangId,opponentId,draft.gangs).some(t=>t.id===stakeId))throw Error(T('Challenge choices changed. Reopen this action.','도전 조건이 바뀌었습니다. 다시 여세요.'));const rows=all(d,draft.gangs),sequence=1+Math.max(0,...rows.map(ch=>Number(ch.sequence)||0)),stake=d.territories.find(t=>t.id===stakeId);ensure(d).challenges.push({id:challengeId,cycle:cy,phase:p,status:'issued',challengerGangId:gangId,defenderGangId:opponentId,challengerPlayerId:challenger.playerId,defenderPlayerId:defender.playerId,stakeId,stakeOwnerBefore:owner(stake),sequence,issuedAt:at,incomingNumber:counters(d,defender.playerId,cy,draft.gangs).received+1,defenderHadIssued:counters(d,defender.playerId,cy,draft.gangs).issued>0});}});
