 const sid=uid(),at=clock(),participantIds=[uid(),uid()];await api().apply(c,{key:`challenges:${id}:session`,label:T('Create challenge battle','도전 전투 만들기'),gangIds:[],mutate(draft){const d=draft.campaign;requireEdit(c);const current=lookup(d,id,draft.gangs);if(!current||current.status!=='accepted')throw Error(T('The challenge is no longer accepted.','수락된 도전이 아닙니다.'));d.sessions??=[];if(d.sessions.some(s=>s.challengeId===id))return;checkChallenge(d,current,draft.gangs);if(!members(d,draft.gangs).some(x=>x.gang.id===current.challengerGangId)||!members(d,draft.gangs).some(x=>x.gang.id===current.defenderGangId))throw Error(T('A participating gang left the campaign.','참가 갱이 캠페인에서 빠졌습니다.'));const s={id:sid,challengeId:id,cycle:current.cycle,campaignPhase:current.phase,territoryId:current.stakeId,challenger:current.challengerGangId,opponent:current.defenderGangId,scenario:'',scenarioNamed:false,date:at.slice(0,10),status:'Active',stage:'pre-battle',round:1,notes:'',participants:[current.challengerGangId,current.defenderGangId].map((gangId,i)=>({id:participantIds[i],gangId,role:i?'defender':'attacker',crew:[],ready:false,creditsEarned:0,reputationChange:0,resources:{}}))};d.sessions.push(s);adopt(d,current).sessionId=sid;}});return (liveCampaign(c).sessions||[]).find(s=>s.challengeId===id)||null;
